def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))

    prefix = [0] * n
    suffix = [0] * n

    prefix[0] = a[0]
    for i in range(1, n):
        prefix[i] = math.gcd(prefix[i-1], a[i])

    suffix[-1] = a[-1]
    for i in range(n-2, -1, -1):
        suffix[i] = math.gcd(suffix[i+1], a[i])

    max_gcd = 0
    for i in range(n):
        if i == 0:
            current = suffix[1]
        elif i == n-1:
            current = prefix[n-2]
        else:
            current = math.gcd(prefix[i-1], suffix[i+1])
        if current > max_gcd:
            max_gcd = current

    print(max_gcd)

