import sys

def main():
    n = int(sys.stdin.readline())
    shops = []
    for _ in range(n):
        f_line = list(map(int, sys.stdin.readline().split()))
        mask = 0
        for idx in range(10):
            if f_line[idx] == 1:
                mask |= (1 << idx)
        p_line = list(map(int, sys.stdin.readline().split()))
        shops.append((mask, p_line))

    max_profit = -float('inf')
    # Iterate through all possible subsets (non-empty)
    for S in range(1, 1 << 10):
        total = 0
        for (mask, p_list) in shops:
            overlap = bin(S & mask).count('1')
            total += p_list[overlap]
        if total > max_profit:
            max_profit = total
    print(max_profit)

